%% PLOT VALUES OF OPENSIM IN MATLAB
%% READ DATA
% This script reads an inverse dynamic file generated by OpenSim.
% It serves as an example for reading your own results.
body_weight=61.9; %kg
clc
currentFolder = pwd; % get current directory
file_name_walking = 'ID_normal_walk_moments.sto'; 
ID_walking = readtable([currentFolder '/' file_name_walking],'FileType',"text");



%% ASSIGN VARIABLES
time_walking = ID_walking.time_1;
% our convention defines plantarflexion as positive -> multiply by -1
ankle_moment_walking = ID_walking.ankle_angle_r_moment*(-1);
%
knee_moment_walking = ID_walking.knee_angle_r_moment;

hip_moment_sag_walking = ID_walking.hip_flexion_r_moment*(-1);

%check sign !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
hip_moment_trans_walking = ID_walking.hip_rotation_r_moment;
%check sign !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
hip_moment_coronal_walking = ID_walking.hip_adduction_r_moment;


currentFolder = pwd; % get current directory
file_name_jogging = 'ID_jogging_moments.sto'; 
ID_jogging = readtable([currentFolder '/' file_name_jogging],'FileType',"text");


time_jogging = ID_jogging.time_1;

% our convention defines plantarflexion as positive -> multiply by -1
ankle_moment_jogging = ID_jogging.ankle_angle_r_moment*(-1);
%
knee_moment_jogging = ID_jogging.knee_angle_r_moment;

hip_moment_sag_jogging = ID_jogging.hip_flexion_r_moment*(-1);

%check sign !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
hip_moment_trans_jogging = ID_jogging.hip_rotation_r_moment;
%check sign !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
hip_moment_coronal_jogging = ID_jogging.hip_adduction_r_moment;


vic_walking = readtable('Walking_moment_vicon.csv','HeaderLines',0,'ReadVariableNames',true);
time_walking_vic  = vic_walking.Time;

% our convention defines plantarflexion as positive -> multiply by -1
ankle_moment_walking_vic = vic_walking.RAnkleMoment;
%
knee_moment_walking_vic  = vic_walking.RKneeMoment;

hip_moment_sag_walking_vic  = vic_walking.RHipMoment;




vic_jogging = readtable('Jogging_moment_vicon.csv','HeaderLines',0,'ReadVariableNames',true);
time_jogging_vic  = vic_jogging.Time;

% our convention defines plantarflexion as positive -> multiply by -1
ankle_moment_jogging_vic = vic_jogging.RAnkleMoment;
%
knee_moment_jogging_vic  = vic_jogging.RKneeMoment;

hip_moment_sag_jogging_vic  = vic_jogging.RHipMoment;



%% PLOT (one gait cycle)
% Find index of initial and final time
x_axis_gait_walking=(time_walking-time_walking(1))*(100/(time_walking(end)-time_walking(1)));
x_axis_gait_jogging=(time_jogging-time_jogging(1))*(100/(time_jogging(end)-time_jogging(1)));

x_axis_gait_walking_vic=(time_walking_vic-time_walking_vic(1))*(100/(time_walking_vic(end)-time_walking_vic(1)));

x_axis_gait_jogging_vic=(time_jogging_vic-time_jogging_vic(1))*(100/(time_jogging_vic(end)-time_jogging_vic(1)));

% obtain the gait cycle
% gait_cycle_t = time(idx_i:idx_f) - time(idx_i);
% gait_cycle = gait_cycle_t / gait_cycle_t(end) * 100;

figure(1)
plot(x_axis_gait_walking,ankle_moment_walking/body_weight,LineWidth=1.5)
hold on
plot(x_axis_gait_walking_vic,ankle_moment_walking_vic,LineWidth=1.5)
title('Ankle moment','FontSize',16)
xlabel('Gait / %','FontSize',16)
ylabel({'(-) Dorsiflexion/(+) Plantarflexion' ,'Moment / Nm/kg'},'FontSize',16)
legend("Opensim","Vicon",'FontSize',16)
grid on
ylim([-2 4])
hold off
exportgraphics(gcf,'ankle_walking_moment.png','Resolution',300)

figure(2)
plot(x_axis_gait_walking,knee_moment_walking/body_weight,LineWidth=1.5)
hold on
plot(x_axis_gait_walking_vic,knee_moment_walking_vic,LineWidth=1.5)
title('Knee moment','FontSize',16)
xlabel('Gait / %','FontSize',16)
ylabel({'(-) Flexion/(+) Extension' ,'Moment / Nm/kg'},'FontSize',16)
legend("Opensim","Vicon",'FontSize',16)
grid on
ylim([-2 2])
hold off
exportgraphics(gcf,'knee_walking_moment.png','Resolution',300)

figure(3)
plot(x_axis_gait_walking,hip_moment_sag_walking/body_weight,LineWidth=1.5)
hold on
